packages/dalph/test/conformance/automati.source:
quintRun({
          backend: "typescript",
          driverFactory: productionDriver(capture, false),
          generation: { mode: "test", test: "automaticSuccessorProductionConformanceTest" },
          maxSamples: 1,
          seed: "385385",
          spec: "specs/acceptedResultIntegration_automaticSuccessor_conformance.qnt",
          stateCheck: stateCheck(
            (raw) => Schema.decodeUnknownEffect(selectedAutomaticSuccessorFields)(raw),
            (model, production) => {
              const matches = model.baseAncestorOfSuccessorHead === production.baseAncestorOfSuccessorHead
              if (!matches) {
                capture.lineageStateMismatch = {
                  model: model.baseAncestorOfSuccessorHead,
                  production: production.baseAncestorOfSuccessorHead
                }
              }
              return matches
            }
          )
        })

packages/dalph/test/conformance/planned-.source:
quintRun({
        backend: "typescript",
        spec: "specs/plannedAttemptExecutor.qnt",
        step: "resumeRedeliveryMbtStep",
        maxSamples: 1,
        maxSteps: 40,
        nTraces: 1,
        seed: "158",
        stateCheck: executorStateCheck,
        driverFactory: {
          create: () =>
            scopedExecutorConformanceDriver
              .create()
              .pipe(
                Effect.map((driver) => ({
                  ...driver,
                  getState: () =>
                    driver.getState === undefined
                      ? Effect.die("executor MBT state observer is missing")
                      : driver
                          .getState()
                          .pipe(
                            Effect.tap((state) =>
                              Ref.set(reached, {
                                intents: state.resumeRecovery.totalRedeliveryIntents,
                                calls: state.resumeRecovery.redeliveryCallCount
                              })
                            )
                          )
                }))
              )
        }
      })

